package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * The sheets and their "today". A sheet starts with the real date the first time it is loaded;
 * from then on {@link #today(String)} is the only date the app uses for that sheet — never the
 * real clock.
 */
@Repository
public class Sheets {

    private final JdbcTemplate jdbc;

    public Sheets(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's today, starting the sheet at the real date when it has never been used. */
    public LocalDate today(String sheetId) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) SELECT ?, ? FROM DUAL "
                + "WHERE NOT EXISTS (SELECT 1 FROM sheet WHERE id = ?)",
                sheetId, Date.valueOf(LocalDate.now()), sheetId);
        return jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId)
                .toLocalDate();
    }

    /**
     * The sheet's next claim number: 1 for its first, then 2, and so on. The sheet's row stays
     * locked until the transaction ends, so two claims opened at once get different numbers, and a
     * number is never given twice.
     */
    public long nextClaimNumber(String sheetId) {
        today(sheetId);
        jdbc.update("UPDATE sheet SET claim_numbers = claim_numbers + 1 WHERE id = ?", sheetId);
        return jdbc.queryForObject("SELECT claim_numbers FROM sheet WHERE id = ?", Long.class, sheetId);
    }

    /**
     * The next number of one of the sheet's period sequences (a period's name, or "X" for claims in
     * no period): 1 for its first, then 2, and so on. Locks the sheet's row as {@link #nextClaimNumber}
     * does, so a number is never given twice.
     */
    public long nextPeriodNumber(String sheetId, String seq) {
        today(sheetId);
        jdbc.update("UPDATE sheet SET claim_numbers = claim_numbers WHERE id = ?", sheetId);
        jdbc.update("MERGE INTO period_number (sheet_id, seq, given) KEY (sheet_id, seq) "
                + "VALUES (?, ?, COALESCE((SELECT given FROM period_number WHERE sheet_id = ? AND seq = ?), 0) + 1)",
                sheetId, seq, sheetId, seq);
        return jdbc.queryForObject("SELECT given FROM period_number WHERE sheet_id = ? AND seq = ?", Long.class, sheetId, seq);
    }

    /** Whether the sheet has been loaded (used) at least once. */
    public boolean exists(String sheetId) {
        return jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, sheetId) > 0;
    }

    /** Whether a steward has archived the sheet: then every change to it is refused. */
    public boolean archived(String sheetId) {
        today(sheetId);
        return Boolean.TRUE.equals(jdbc.queryForObject("SELECT archived FROM sheet WHERE id = ?", Boolean.class, sheetId));
    }

    public void archive(String sheetId) {
        today(sheetId);
        jdbc.update("UPDATE sheet SET archived = TRUE, archived_on = today WHERE id = ?", sheetId);
    }

    public void setToday(String sheetId, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheetId, Date.valueOf(today));
    }
}
        java.util.Set<String> used = new java.util.HashSet<>();
        for (String other : treeOf(sheetId)) {
            used.addAll(jdbc.queryForList("SELECT name_key FROM PUBLIC.person WHERE sheet_id = ?", String.class, other));
            used.addAll(jdbc.queryForList("SELECT alias_key FROM PUBLIC.person_alias WHERE sheet_id = ?", String.class, other));
        }
        return used;
    }

    /** The other sheets of the sheet's tree, among the sheets that exist: its ancestors (its parent, the
     *  parent's parent, and so on) and its descendants (the sheets naming it as parent, their children,
     *  and so on). Not dated: read from the live sheets. */
    public java.util.Set<String> treeOf(String sheetId) {
        java.util.Set<String> tree = new java.util.LinkedHashSet<>();
        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
        for (String sheet = parentOf(sheetId); sheet != null && seen.add(sheet); sheet = parentOf(sheet)) {
            tree.add(sheet);
        }
        java.util.ArrayDeque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
        java.util.Set<String> visited = new java.util.HashSet<>(List.of(sheetId));
        while (!todo.isEmpty()) {
            for (String child : jdbc.queryForList("SELECT sheet_id FROM PUBLIC.sheet_setting WHERE parent_id = ?",
                    String.class, todo.poll())) {
                if (visited.add(child)) {
                    todo.add(child);
                    tree.add(child);
                }
            }
        }
        tree.remove(sheetId);
        tree.removeIf(sheet -> {
            Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM PUBLIC.sheet WHERE id = ?", Integer.class, sheet);
            return n == null || n == 0;
        });
        return tree;
    }

    private String parentOf(String sheetId) {
        return jdbc.queryForList("SELECT parent_id FROM PUBLIC.sheet_setting WHERE sheet_id = ?", String.class, sheetId)
                .stream().filter(p -> p != null && !p.isBlank()).findFirst().orElse(null);
    }

    /** Whether anyone on this sheet already has this as an alias. */
    private boolean aliasTaken(String sheetId, String alias) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(TRIM(?))",
                Integer.class, sheetId, alias);
    }

    /** The sheet's parent sheet: a grade with no rate in force on a date on this sheet takes the
     *  parent's then (see {@link net.officefloor.hq.app.rate.Rates#pct}). Null when unset (none). Not
     *  dated: read from the live sheet, so an as-of view shows it too. */
    public String parent(String sheetId) {
        List<String> values = jdbc.query("SELECT parent_id FROM PUBLIC.sheet_setting WHERE sheet_id = ?",
                (rs, i) -> rs.getString("parent_id"), sheetId);
        return values.isEmpty() ? null : values.get(0);
    }

    public void setParent(String sheetId, String parent) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, parent_id) KEY (sheet_id) VALUES (?, ?)", sheetId, parent);
    }

    /** The sheet's descendants: its children (the sheets naming it as their parent), their children,
     *  and so on, nearest first. Not dated: read from the live sheets. */
    public List<String> descendants(String sheetId) {
        java.util.Set<String> seen = new java.util.LinkedHashSet<>();
        seen.add(sheetId);
        java.util.ArrayDeque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
        while (!todo.isEmpty()) {
            for (String child : jdbc.query("SELECT sheet_id FROM PUBLIC.sheet_setting WHERE parent_id = ? ORDER BY sheet_id",
                    (rs, i) -> rs.getString("sheet_id"), todo.poll())) {
                if (seen.add(child)) todo.add(child);
            }
        }
        seen.remove(sheetId);
        return List.copyOf(seen);
    }

    /** Whether the sheet `ancestor` is the sheet `sheetId` or one of its parents, any number of levels up. */
    public boolean isAncestor(String ancestor, String sheetId) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        for (String sheet = sheetId; sheet != null && seen.add(sheet); sheet = parent(sheet)) {
            if (sheet.equals(ancestor)) return true;
        }
        return false;
    }

    /** The sheet's entry date: while set, the default date of a new claim in place of the sheet's
     *  today. Null when unset (off). */
    public LocalDate entryDate(String sheetId) {
        List<Date> values = jdbc.query("SELECT entry_date FROM sheet_setting WHERE sheet_id = ?",
                (rs, i) -> rs.getDate("entry_date"), sheetId);
        return values.isEmpty() || values.get(0) == null ? null : values.get(0).toLocalDate();
